<?php
namespace App\Http\Controllers;
use App\Models\{Product,Sale};use App\Services\InventoryTransactionService;use Illuminate\Http\Request;
class SaleController extends Controller {
 public function index(Request $r){$filters=$r->validate(['search'=>['nullable','string','max:40'],'status'=>['nullable','in:completed,cancelled'],'from'=>['nullable','date'],'to'=>['nullable','date']]);if(!empty($filters['from'])&&!empty($filters['to'])&&$filters['to']<$filters['from'])throw \Illuminate\Validation\ValidationException::withMessages(['to'=>'Tanggal akhir harus sama atau setelah tanggal awal.']);$q=Sale::with('user')->withCount('items')->when(!$r->user()->isAdmin(),fn($q)=>$q->where('user_id',$r->user()->id))->when($r->filled('search'),fn($q)=>$q->where('sale_number','like','%'.$r->query('search').'%'))->when($r->filled('status'),fn($q)=>$q->where('status',$r->query('status')))->when($r->filled('from'),fn($q)=>$q->whereDate('sold_at','>=',$r->query('from')))->when($r->filled('to'),fn($q)=>$q->whereDate('sold_at','<=',$r->query('to')))->latest('sold_at');$sales=$q->paginate(15)->withQueryString();return view('sales.index',compact('sales'));}
 public function create(){return view('sales.create',['products'=>Product::orderBy('name')->get()]);}
 public function store(Request $r,InventoryTransactionService $service){$items=collect($r->input('items',[]))->filter(fn($item)=>filled($item['product_id']??null)||filled($item['quantity']??null))->values()->all();$r->merge(['items'=>$items]);$data=$r->validate(['items'=>['required','array','min:1','max:10'],'items.*.product_id'=>['required','integer','distinct','exists:products,id'],'items.*.quantity'=>['required','integer','min:1','max:100000']]);$sale=$service->sale($data,$r->user()->id);return redirect()->route('sales.show',$sale)->with('success','Penjualan tersimpan. Stok dan total sudah diperbarui.');}
 public function show(Request $r,Sale $sale){abort_unless($r->user()->isAdmin()||$sale->user_id===$r->user()->id,403);$sale->load(['user','items.product']);return view('sales.show',compact('sale'));}
 public function cancel(Sale $sale,InventoryTransactionService $service){abort_unless(auth()->user()->isAdmin(),403);$service->cancelSale($sale);return back()->with('success','Penjualan dibatalkan dan stok dipulihkan.');}
}
